import { PHOTOS, type PhotoKey } from "./photo-credits";

/**
 * Responsive stock photo: AVIF with a WebP fallback at the widths generated by
 * scripts/optimize-images.mjs. Width/height reserve the space (no layout shift); photos are
 * only used below the fold, so they load lazily.
 *
 * `.photo-reveal` (index.css) adds the scroll-linked reveal: an inset clip-path opening and a
 * gentle scale-down, as a CSS scroll-driven animation (no JS). Without scroll-timeline
 * support, or with motion off, the photo is simply shown.
 */
export function Photo({
  photo,
  sizes,
  className = "",
}: {
  photo: PhotoKey;
  sizes: string;
  className?: string;
}) {
  const { file, widths, width, height, alt } = PHOTOS[photo];
  const srcset = (format: "avif" | "webp") =>
    widths.map((w) => `/img/${file}-${w}w.${format} ${w}w`).join(", ");
  return (
    <div className={`photo-reveal overflow-hidden rounded-3xl bg-mint-100 ${className}`}>
      <picture>
        <source type="image/avif" srcSet={srcset("avif")} sizes={sizes} />
        <img
          src={`/img/${file}-${widths[1]}w.webp`}
          srcSet={srcset("webp")}
          sizes={sizes}
          width={width}
          height={height}
          alt={alt}
          loading="lazy"
          decoding="async"
          className="photo-reveal-img block h-full w-full object-cover"
        />
      </picture>
    </div>
  );
}
